        "prompt": "Một bơm không khí có thể tích 0,125 l và áp suất của bơm không khí trong bơm là 1 atm. Dùng bơm\nđể bơm không khí vào một quả bóng có dung tích không đổi là 2,5 l. Giả sử ban đầu áp suất của khí trong bình\nlà 1 atm và nhiệt độ của quả bóng là không thay đổi trong suốt quá trình bơm. Hãy xác định áp suất của khối\nkhí trong bóng sau 12 lần bơm.",
