        "prompt": "Một bơm xe đạp hình trụ có đường kính trong là 3 cm. Người ta dùng ngón tay bịt kín đầu vòi bơm\nvà ấn pit-tông từ từ để nén không khí trong bơm sao cho nhiệt độ không thay đổi. Lấy áp suất khí quyển là p<sub>0</sub>\n= 10<sup>5</sup> Pa. Khi thể tích của không khí trong bơm giảm đi 4 lần thì lực tác dụng lên pit-tông bằng bao nhiêu N?",
