        "question": "Một quả bóng da có dung tích 2,0 lít chứa không khí ở áp suất 8.10<sup>5</sup> Pa . Người ta bơm không khí ở\náp suất 10<sup>5</sup> Pa vào bóng. Mỗi lần bơm được 160cm3 không khí.",
