        "prompt": "Trong một ống nhỏ dài, một đầu kín, một đầu hở, tiết diện đều, ban đầu đặt ống thẳng đứng miệng\nống hướng lên, trong ống về phía đáy có cột không khí dài 40cm và được ngăn cách với bên ngoài bằng cột\nthủy ngân dài h = 12 cm. Áp suất khí quyển 76cmHg và nhiệt độ không đổi. Tính chiều cao của cột không\nkhí trong ống với ống đặt nằm ngang?",
